<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Common\Application\Usecase\Install;

use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeWriteGateway;
use Civi\Lughauth\Features\Document\Theme\Domain\Theme;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeAttributes;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionWriteGateway;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersion;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionAttributes;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionChannelOptions;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetWriteGateway;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAsset;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAssetAttributes;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetContentVO;

class InstallCorporateTheme
{
    // FIXME: sospecho que debería ser un __DIR__ . '/assets'
    private const string STYLE_DIR = __DIR__ . '/../../../../../Oidc/Theme/Themes/corporate/style/';

    public function __construct(
        private readonly ThemeWriteGateway $themes,
        private readonly ThemeVersionWriteGateway $versions,
        private readonly ThemeAssetWriteGateway $assets,
    ) {
    }

    public function install(): void
    {
        $this->installCorporateHtml();
        $this->installCorporateFullHtml();
        $this->installCorporateMail();
    }

    // -------------------------------------------------------------------------

    private function installCorporateHtml(): void
    {
        $theme = $this->createTheme('corporate');

        $layout = <<<'HANDLEBARS'
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{{title}}</title>
    <link rel="icon" type="image/png" href="{{theme_assets_path}}/favicon.png">
    <link rel="stylesheet" href="{{theme_assets_path}}/corporate.css">
</head>
<body>
    <div class="background-image">
        <picture>
            <source media="(max-width: 480px)" srcset="{{theme_assets_path}}/office_480x800.webp" type="image/webp">
            <source media="(max-width: 768px)" srcset="{{theme_assets_path}}/office_768x1024.webp" type="image/webp">
            <source media="(max-width: 1024px)" srcset="{{theme_assets_path}}/office_1024x768.webp" type="image/webp">
            <source media="(max-width: 1440px)" srcset="{{theme_assets_path}}/office_1440x900.webp" type="image/webp">
            <source media="(min-width: 1441px)" srcset="{{theme_assets_path}}/office_1920x1080.webp" type="image/webp">
            <source media="(max-width: 480px)" srcset="{{theme_assets_path}}/office_480x800.jpeg">
            <source media="(max-width: 768px)" srcset="{{theme_assets_path}}/office_768x1024.jpeg">
            <source media="(max-width: 1024px)" srcset="{{theme_assets_path}}/office_1024x768.jpeg">
            <source media="(max-width: 1440px)" srcset="{{theme_assets_path}}/office_1440x900.jpeg">
            <img src="{{theme_assets_path}}/office_1920x1080.jpeg" alt="Corporate office background" class="bg-img" loading="lazy">
        </picture>
        <div class="background-overlay"></div>
    </div>
    <div class="main-container">
        <div class="content-wrapper">
            <div class="header">
                <img src="{{theme_assets_path}}/logo.png" alt="Company Logo" class="company-logo" />
            </div>
            {{{slot_content}}}
        </div>
    </div>
    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const formContent = document.querySelector('.form-content');
            const loadingIndicator = document.querySelector('.loading');
            formContent.classList.add('slide-in');
            setTimeout(function() {
                const forms = formContent.querySelectorAll('form');
                forms.forEach(form => {
                    function handleFormSubmit(event) {
                        event.preventDefault();
                        formContent.classList.add('slide-out');
                        loadingIndicator.style.display = 'block';
                        setTimeout(function() {
                            form.removeEventListener('submit', handleFormSubmit);
                            form.submit();
                        }, 500);
                    }
                    const existingSubmitListener = form.onsubmit;
                    if (existingSubmitListener) {
                        form.addEventListener('submit', function(event) {
                            existingSubmitListener.call(form, event);
                            handleFormSubmit(event);
                        });
                    } else {
                        form.addEventListener('submit', handleFormSubmit);
                    }
                });
            }, 10);
        });
    </script>
</body>
</html>
HANDLEBARS;

        $this->createVersion($theme, ThemeVersionChannelOptions::HTML, $layout);
        $this->installAssets($theme);
    }

    private function installCorporateMail(): void
    {
        $theme = $this->createTheme('corporate-mail');

        $layout = <<<'HANDLEBARS'
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{{subject}}</title>
</head>
<body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;padding:24px 0;">
  <tr>
    <td align="center">
      <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:8px;overflow:hidden;">
        <tr>
          <td style="background:#1d4ed8;padding:24px 32px;">
            <p style="margin:0;font-size:22px;font-weight:bold;color:#ffffff;">LughAuth</p>
          </td>
        </tr>
        <tr>
          <td style="padding:32px;">
            {{{slot_content}}}
          </td>
        </tr>
        <tr>
          <td style="background:#f9fafb;padding:16px 32px;text-align:center;font-size:12px;color:#6b7280;">
            This message was sent automatically. Please do not reply.
          </td>
        </tr>
      </table>
    </td>
  </tr>
</table>
</body>
</html>
HANDLEBARS;

        $this->createVersion($theme, ThemeVersionChannelOptions::MAIL, $layout);
        // Mail theme has no binary assets
    }

    private function installCorporateFullHtml(): void
    {
        $theme = $this->createTheme('corporate-full');

        $layout = <<<'HANDLEBARS'
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{{title}}</title>
    <link rel="icon" type="image/png" href="{{theme_assets_path}}/favicon.png">
    <link rel="stylesheet" href="{{theme_assets_path}}/corporate.css">
    <link rel="stylesheet" href="{{theme_assets_path}}/full.css">
    <link rel="stylesheet" href="{{theme_assets_path}}/profile.css">
</head>
<body class="full-window">
    <header class="app-header">
        <div class="app-header-inner">
            <a class="app-logo" href="/">
                <img src="{{theme_assets_path}}/logo.png" alt="Company Logo" />
            </a>
        </div>
    </header>
    <main class="app-main">
        <div class="app-content">
            {{{slot_content}}}
        </div>
    </main>
</body>
</html>
HANDLEBARS;

        $this->createVersion($theme, ThemeVersionChannelOptions::HTML, $layout);
        $this->installAssets($theme);
    }

    // -------------------------------------------------------------------------

    private function createTheme(string $name): Theme
    {
        $attr = new ThemeAttributes();
        $attr->uid(Random::comb());
        $attr->name($name);
        $attr->isDefault(true);
        $attr->enabled(true);
        $created = $this->themes->create(Theme::create($attr));
        $this->themes->update($created, $created->enable());

        return $created;
    }

    private function createVersion(Theme $theme, ThemeVersionChannelOptions $channel, string $contentHtml): void
    {
        $attr = new ThemeVersionAttributes();
        $attr->uid(Random::comb());
        $attr->theme($theme);
        $attr->channel($channel);
        $attr->contentHtml($contentHtml);
        $this->versions->create(ThemeVersion::create($attr));
    }

    private function installAssets(Theme $theme): void
    {
        $styleDir = self::STYLE_DIR;

        if (!is_dir($styleDir)) {
            return;
        }

        foreach (glob($styleDir . '*') ?: [] as $filePath) {
            if (!is_file($filePath)) {
                continue;
            }
            $filename = basename($filePath);
            $binary   = BinaryContent::fromFile($filePath);
            $tempKey  = $this->assets->temporalStoreContent($binary);

            $attr = new ThemeAssetAttributes();
            $attr->uid(Random::comb());
            $attr->theme($theme);
            $attr->code($filename);
            $attr->type($binary->mime);
            $attr->content(ThemeAssetContentVO::fromTemporal($tempKey));
            $attr->enabled(true);

            $this->assets->create(ThemeAsset::create($attr));
            $this->assets->commitContent($tempKey);
        }
    }
}
